import{_ as o,l,o as e,c as T,v as t,p as i,x as r,d as n,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"TLS 入口","description":"","frontmatter":{"title":"TLS 入口","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/http-tls-entry.md","filePath":"cs/http-tls-entry.md","lastUpdated":1789023840000}'),p={name:"cs/http-tls-entry.md"};function h(E,a,P,S,_,f){const s=l("Mermaid");return e(),T("div",null,[a[1]||(a[1]=t('<h1 id="tls-入口" tabindex="-1">TLS 入口 <a class="header-anchor" href="#tls-入口" aria-label="Permalink to &quot;TLS 入口&quot;">​</a></h1><div class="epigraph"><p>HTTP 的方法与正文若在明文 TCP 上走，任何中间盒都能读和改；应用需要一条带真实性的信道。</p><footer>—— 据 Rescorla, RFC 8446, The Transport Layer Security Protocol Version 1.3, 2018 的问题设定整理</footer></div><p><a href="/cs/http2">上一课</a>把文档语义钉在请求—响应上，默认假设字节不被篡改。互联网路径经过 <a href="/cs/bgp-intuition">BGP</a> 与 <a href="/cs/dhcp-nat">NAT</a>，运营者与攻击者都可以做中间人。缺口不是再发明一种方法动词，而是承认：<strong>HTTP 需要带认证（及通常保密）的通道</strong>。完整握手是安全课 <a href="/cs/tls-handshake">TLS 握手</a>，本课不写密钥交换步骤。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DNS 给出的 IP 不证明「对方是证书里的那个名字」。TCP 三次握手只同步序号，任何人都能完成。明文 <code>GET</code> 可被注入广告或改登录口。缺口是传输之上（或 QUIC 之内）的一层：对端认证、机密性、完整性，然后才跑 HTTP 语义。HTTPS 只是把 URL 方案换成在 TLS 上的 HTTP，不是新的方法集合。</p><p>本课不给证书链验证算法，不画 ClientHello 字段。</p><p><span class="marginnote">真实性：你连上的是你以为的服务器。完整性：字节途中不被改。保密：旁路读不懂。三者可拆，Web 通常一起要。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>部署直觉：浏览器对 <code>https</code> URI 先建立 TCP（或直接 QUIC），再在安全课将学的握手里拿到对称密钥，之后 HTTP 请求作为密文写进去。证书把公钥绑到 DNS 名字——名字来自上一课。失败则整页不加载，而不是「明文凑合」。</p>',9)),(e(),i(c,null,{default:r(()=>[d(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HTTP%5B%22HTTP%20%E8%AF%AD%E4%B9%89%22%5D%20--%3E%20NEED%5B%22%E9%9C%80%E8%A6%81%E7%9C%9F%E5%AE%9E%E4%BF%A1%E9%81%93%22%5D%0A%20%20NEED%20--%3E%20TLS%5B%22%E5%90%8E%E8%AF%BE%3A%20TLS%20%E6%8F%A1%E6%89%8B%22%5D%0A%20%20NEED%20--%3E%20QUIC%5B%22QUIC%20%E5%B7%B2%E5%86%85%E7%BD%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/layering-e2e">端到端论证</a>在这里变成：链路 FCS 与 IP 校验都不认证发送者是谁。认证必须对着名字（或固定公钥），在真正的通信两端做。CDN 下一课会在地理上插入「准端」，证书与名字如何匹配是部署问题，本课只要求「HTTP 不能裸奔」。</p><p>与 OS：<a href="/cs/socket-api">套接字</a> 仍是 <code>read</code>/<code>write</code>；是否套上 TLS 由库或内核 kTLS 决定，对象不变。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课明确不写握手、不写密码套件谈判、不写 0-RTT 重放。那些是 <code>/cs/tls-handshake</code>。也不把证书透明与吊销列表展开。中间盒企业 TLS 拦截是政策与安全课。</p><p>HSTS 与升级方案是部署策略，不是本课的握手。混合内容（页面 HTTPS、图片 HTTP）会把真实性缺口从文档缝里漏回去。</p><p>证书过期与名字不匹配都应失败关闭，不能回落到明文 HTTP。</p><p>后课默认：Web 流量应走有真实性的通道。同一对象从近处缓存取出以降延迟，下一课 CDN 直觉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>明文 HTTP 无真实性；HTTPS 是 HTTP over 认证加密信道。</li><li>握手与证书验证留给 <a href="/cs/tls-handshake">TLS 握手</a>。</li><li>延迟与缓存是 CDN 的缺口。</li><li>出处：RFC 8446（问题与位置）；RFC 9110 对 https；Kurose and Ross。</li></ul>',10))])}const C=o(p,[["render",h]]);export{m as __pageData,C as default};
